SELECT O.OBRA NOME, COUNT(DISTINCT V.ID) VIDEOS, COUNT(DISTINCT O.NOME) PARTES, MAX(S.STATUS) STATUS FROM (SELECT N.ID, N.NOME, COALESCE(M.OBRA, N.NOME) OBRA FROM LIVROS_NOMES N LEFT JOIN OBRA_DE M ON M.NOME COLLATE utf8mb4_0900_ai_ci = N.NOME WHERE N.ESTADO = 'SAGRADO') O LEFT JOIN LIVROS_INDICADOS L ON L.TITULO COLLATE utf8mb4_0900_ai_ci = O.NOME LEFT JOIN VIDEOS V ON V.ID = L.VIDEO_ID AND ({{canalId}} = 0 OR V.CANAL_ID = {{canalId}}) LEFT JOIN ITENS_STATUS S ON S.TIPO = 'SAGRADO' AND S.NOME COLLATE utf8mb4_0900_ai_ci = O.OBRA WHERE ({{canalId}} = 0 OR V.ID IS NOT NULL) AND ('{{busca}}' = '' OR O.OBRA LIKE CONCAT('%', '{{busca}}', '%') OR O.NOME LIKE CONCAT('%', '{{busca}}', '%')) AND ('{{status}}' = '' OR ('{{status}}' = 'NENHUM' AND COALESCE(S.STATUS, '') = '') OR S.STATUS = '{{status}}') AND ('{{fav}}' = '' OR EXISTS (SELECT 1 FROM ITENS_FAVORITOS FV WHERE FV.TIPO = 'SAGRADO' AND FV.NOME COLLATE utf8mb4_0900_ai_ci = O.OBRA)) GROUP BY O.OBRA ORDER BY IF('{{ordem}}' = 'az', 0, COUNT(DISTINCT V.ID)) DESC, O.OBRA LIMIT {{limit}} OFFSET {{offset}}